// The web shell for an amenui application: `mount(stage, opts)` starts the module in a stage element
// and forwards the pointer, wheel, keys, text, the input method, the clipboard and the size to it,
// keeps the accessibility mirror (a hidden DOM tree of roles and names) in step, and draws frames only
// while the runtime needs them.
//
// The stage holds a canvas `.c`, a textarea `.ta` (the text agent), a `.a11y` element (the mirror) and
// optionally a `.msg` loading message; `stage()` makes one. The module is the application's wasm-bindgen
// output (exports generated by `amenui::web_app!`), already initialised.
//
// opts: { module, fonts: [sans, pixel, mono] (URLs, ArrayBuffers or Uint8Arrays), hash, ownsHash,
//         onRoute(hash), keys (the element that takes keys; window by default), shortcuts (extra
//         Ctrl/⌘ letters the application handles), after(module) (after every handled event),
//         onWarm(done, total) (the renderer's warm-up, each step; (1, 1) when it is done),
//         failed (the text shown when graphics cannot start),
//         faces, assets (where a face or resource the page asks for is: a map of name → URL, or a
//         function of the name; the framework fetches nothing itself, this shell does when
//         `faces_wanted` / `assets_wanted` name something),
//         preload (face names to fetch together with the module, added before the first frame so the
//         page never shows their stand-ins) }

const bytes = async f => f instanceof Uint8Array ? f : f instanceof ArrayBuffer ? new Uint8Array(f) : new Uint8Array(await (await fetch(f)).arrayBuffer());

/** The styles a stage needs (put once in the document or the shadow root). */
export const css = `
  .stage { position: relative; width: 100%; height: 100%; }
  .stage canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; outline: none;
    user-select: none; -webkit-user-select: none; -webkit-touch-callout: none; -webkit-tap-highlight-color: transparent; }
  .stage .msg { position: absolute; inset: 0; display: grid; place-items: center; padding: 16px; text-align: center; }
  .stage .a11y { position: absolute; inset: 0; opacity: 0; pointer-events: none; overflow: hidden; }
  .stage .a11y div { position: fixed; overflow: hidden; white-space: nowrap; color: transparent; }
  .stage .ta { position: absolute; left: 0; top: 0; width: 2px; height: 20px; padding: 0; border: 0; margin: 0; resize: none; overflow: hidden;
    opacity: 0; color: transparent; background: transparent; caret-color: transparent; outline: none; white-space: pre; pointer-events: none; }
`;

/** A stage element with its canvas, text agent, mirror and loading message. */
export function stage({ loading = 'Loading…', textLabel = 'Text input' } = {}) {
  const s = document.createElement('div');
  s.className = 'stage';
  s.innerHTML = '<canvas class="c" tabindex="0"></canvas><textarea class="ta" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" tabindex="-1"></textarea><div class="a11y"></div><div class="msg"></div>';
  s.querySelector('.ta').setAttribute('aria-label', textLabel);
  s.querySelector('.msg').textContent = loading;
  return s;
}

export async function mount(stage, opts) {
  const root = stage.getRootNode();
  const active = () => (root.activeElement !== undefined ? root.activeElement : document.activeElement);

  const msg = stage.querySelector('.msg'), canvas = stage.querySelector('.c');
  try {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const fit = () => { const r = stage.getBoundingClientRect(); canvas.width = Math.max(1, Math.floor(r.width * dpr)); canvas.height = Math.max(1, Math.floor(r.height * dpr)); };
    fit();
    const w = opts.module;
    const urlOf = (src, name) => (typeof src === 'function' ? src(name) : src && src[name]);
    const pre = Promise.all((opts.preload || []).map(n => { const u = urlOf(opts.faces, n); return u ? bytes(u).then(b => [n, b], () => null) : null; }));
    const [sans, pixel, mono] = await Promise.all(opts.fonts.map(bytes));
    await w.start(canvas, sans, pixel, mono, dpr, opts.hash || '');
    // Faces and resources the page asks for: each fetched once; when its bytes come the page takes it.
    const asked = new Set();
    for (const p of await pre) if (p && w.add_face) { asked.add(p[0]); w.add_face(p[0], p[1], performance.now() / 1000); }
    const fetchWanted = () => {
      for (const [list, src, add] of [[w.faces_wanted, opts.faces, w.add_face], [w.assets_wanted, opts.assets, w.add_asset]]) {
        if (!list || !src || !add) continue;
        for (const name of JSON.parse(list())) {
          if (asked.has(name)) continue;
          asked.add(name);
          const u = urlOf(src, name);
          if (u) bytes(u).then(b => { add(name, b, now()); kick(); }, () => {});
        }
      }
    };
    if (msg) msg.remove();
    canvas.focus();
    const now = () => performance.now() / 1000;
    const at = e => { const r = canvas.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; };
    // The page is in the hash (plain names such as #button), so it can be linked; Back goes back. An
    // embedded view tells its host instead (`amenui-route`).
    let shown = '';
    const sync = () => { const h = '#' + w.hash(); if (h === shown) return; shown = h; if (opts.ownsHash && location.hash !== h) location.hash = h; if (opts.onRoute) opts.onRoute(h.slice(1)); };
    if (opts.ownsHash) window.addEventListener('hashchange', () => { if (!w.route(location.hash)) sync(); });
    sync();
    // Frames on demand: the animation-frame loop runs only while the framework needs frames; when it
    // does not, the loop stops, and input or a timed wake (the caret's blink, a clock) starts it again.
    // The renderer warms up over the first frames (`Ui::warm`): the stage is busy until it is done, and
    // `opts.onWarm(done, total)` hears each step (and `(1, 1)` once at the end).
    let warming = true;
    const warmUpdate = () => {
      if (!warming || !w.warm) return;
      const p = w.warm();
      if (opts.onWarm) { if (p.length) opts.onWarm(p[0], p[1]); else opts.onWarm(1, 1); }
      if (!p.length) { warming = false; stage.removeAttribute('aria-busy'); }
    };
    stage.setAttribute('aria-busy', 'true');
    let raf = 0, timer = 0;
    const loop = () => {
      raf = 0; if (timer) { clearTimeout(timer); timer = 0; }
      const d = w.frame(now());
      axUpdate();
      fetchWanted();
      warmUpdate();
      if (d === 0) raf = requestAnimationFrame(loop);
      else if (d > 0) timer = setTimeout(kick, d * 1000);
    };
    const kick = () => { if (!raf) raf = requestAnimationFrame(loop); };
    // The warm-up goes on in idle time, whether or not the page draws (a page at rest draws nothing):
    // each idle period makes the next pieces and draws nothing; a frame only when the material arrives.
    // Without requestIdleCallback, an animation frame that does warm-up work only.
    const idle = window.requestIdleCallback ? f => requestIdleCallback(f, { timeout: 200 }) : f => requestAnimationFrame(() => f(null));
    const warmIdle = d => {
      if (!w.warm_idle) return;
      const ms = d && !d.didTimeout ? Math.max(1, Math.min(d.timeRemaining(), 6)) : 6;
      const r = w.warm_idle(ms, now());
      if (r & 2) kick();
      warmUpdate();
      if (r & 1) idle(warmIdle);
    };
    idle(warmIdle);
    // Text: while a text field has focus the hidden text element sits at its caret and has the keyboard.
    const ta = stage.querySelector('.ta');
    const syncText = () => {
      const r = w.ime_rect();
      if (r.length) {
        ta.style.left = r[0] + 'px'; ta.style.top = r[1] + 'px'; ta.style.height = Math.max(r[3], 10) + 'px'; ta.style.fontSize = Math.max(r[3] * 0.8, 10) + 'px';
        if (active() !== ta) ta.focus({ preventScroll: true });
      } else if (active() === ta) canvas.focus({ preventScroll: true });
      canvas.style.cursor = w.cursor();
    };
    // The accessibility mirror, kept in step with what the framework reports changed.
    const ax = stage.querySelector('.a11y'), els = new Map();
    const axUpdate = () => {
      const c = canvas.getBoundingClientRect();
      for (const op of JSON.parse(w.a11y_update())) {
        if (op.remove !== undefined) { const e = els.get(op.remove); if (e) { e.remove(); els.delete(op.remove); } continue; }
        if (op.focus !== undefined) {
          // Focus follows only while assistive technology is in the mirror; otherwise the canvas (or the
          // text element) keeps the keyboard.
          const e = op.focus && els.get(op.focus);
          if (e && ax.contains(active()) && active() !== e) e.focus({ preventScroll: true });
          continue;
        }
        const n = op.set;
        let e = els.get(n.key);
        if (!e) {
          e = document.createElement('div');
          els.set(n.key, e);
          e.addEventListener('click', ev => { ev.stopPropagation(); w.a11y_activate(n.key, now()); after(); });
          e.addEventListener('focus', () => { w.a11y_focus(n.key, now()); after(); });
        }
        const parent = (n.parent && els.get(n.parent)) || ax;
        if (e.parentNode !== parent) parent.appendChild(e);
        for (const a of ['role', 'aria-label', 'aria-checked', 'aria-selected', 'aria-valuenow', 'aria-valuemin', 'aria-valuemax', 'aria-modal', 'aria-level', 'aria-disabled', 'aria-expanded', 'aria-description', 'aria-live', 'aria-invalid', 'aria-required', 'tabindex']) e.removeAttribute(a);
        if (n.role === 'text') { if (e.textContent !== n.name) e.textContent = n.name; }
        else {
          e.setAttribute('role', n.role);
          e.setAttribute('aria-label', n.name);
          if (n.role === 'textbox') e.textContent = n.text || '';
        }
        if (n.checked !== undefined) e.setAttribute('aria-checked', n.checked);
        if (n.selected !== undefined) e.setAttribute('aria-selected', n.selected);
        if (n.value) { e.setAttribute('aria-valuenow', n.value[0]); e.setAttribute('aria-valuemin', n.value[1]); e.setAttribute('aria-valuemax', n.value[2]); }
        if (n.modal) e.setAttribute('aria-modal', 'true');
        if (n.level) e.setAttribute('aria-level', n.level);
        if (n.disabled) e.setAttribute('aria-disabled', 'true');
        if (n.expanded !== undefined) e.setAttribute('aria-expanded', n.expanded);
        if (n.description) e.setAttribute('aria-description', n.description);
        if (n.live) e.setAttribute('aria-live', n.live);
        if (n.invalid) e.setAttribute('aria-invalid', 'true');
        if (n.required) e.setAttribute('aria-required', 'true');
        if (n.focusable) e.setAttribute('tabindex', '-1');
        const r = n.rect;
        e.style.left = (c.left + r[0]) + 'px'; e.style.top = (c.top + r[1]) + 'px'; e.style.width = Math.max(r[2], 1) + 'px'; e.style.height = Math.max(r[3], 1) + 'px';
      }
    };
    // A copy button in the page asks for the clipboard: hand its text to the browser after the event.
    const clip = () => { const t = w.take_clipboard(); if (t != null && navigator.clipboard) navigator.clipboard.writeText(t).catch(() => {}); };
    const after = () => { sync(); syncText(); axUpdate(); clip(); if (opts.after) opts.after(w); kick(); };
    // Mouse, pen and touch come as pointer events (kind 0, 2, 1); the pointer is captured while it is
    // down, so a drag keeps going outside the canvas.
    const kind = e => e.pointerType === 'touch' ? 1 : e.pointerType === 'pen' ? 2 : 0;
    canvas.addEventListener('pointermove', e => {
      for (const c of (e.getCoalescedEvents ? e.getCoalescedEvents() : [e])) w.pointer_move(e.pointerId, kind(e), ...at(c), now(), (c.timeStamp || e.timeStamp) / 1000);
      canvas.style.cursor = w.cursor(); kick();
    });
    canvas.addEventListener('pointerleave', e => { if (kind(e) !== 1) { w.pointer_leave(now()); kick(); } });
    // The page decides where focus goes (the canvas, or the text element when a field is pressed), so the
    // browser's own focus change on press is suppressed. Only the primary button presses.
    canvas.addEventListener('pointerdown', e => {
      e.preventDefault();
      if (kind(e) === 0 && e.button !== 0) return;
      canvas.focus({ preventScroll: true }); canvas.setPointerCapture(e.pointerId);
      const [x, y] = at(e);
      if (kind(e) !== 1) w.pointer_move(e.pointerId, kind(e), x, y, now(), e.timeStamp / 1000);
      w.pointer_down(e.pointerId, kind(e), x, y, e.shiftKey, now(), e.timeStamp / 1000); after();
    });
    canvas.addEventListener('pointerup', e => { if (kind(e) === 0 && e.button !== 0) return; w.pointer_up(e.pointerId, kind(e), ...at(e), now()); after(); });
    canvas.addEventListener('pointercancel', e => { w.pointer_cancel(e.pointerId, now()); after(); });
    canvas.addEventListener('contextmenu', e => e.preventDefault());
    // Wheel deltas in pixels; lines are 40 px (as on the native window), pages the canvas's height. A
    // trackpad's own momentum comes as more wheel events, so none is added. A pinch arrives as a wheel
    // with Ctrl: it is not a scroll, and the page is not zoomed.
    canvas.addEventListener('wheel', e => {
      e.preventDefault();
      if (e.ctrlKey) return;
      const k = e.deltaMode === 1 ? 40 : e.deltaMode === 2 ? canvas.clientHeight : 1;
      w.wheel(...at(e), e.deltaX * k, e.deltaY * k, now()); kick();
    }, { passive: false });
    (opts.keys || window).addEventListener('keydown', e => {
      // Keys the input method is composing with are its own.
      if (e.isComposing || e.keyCode === 229) return;
      const cmd = e.ctrlKey || e.metaKey;
      if (cmd) {
        const k = e.key.toLowerCase();
        // Copy, cut and paste arrive as clipboard events; the application's own shortcuts are
        // `opts.shortcuts` (select all, undo and redo always); other shortcuts belong to the browser.
        if (!['a', 'z', 'y', ...(opts.shortcuts || [])].includes(k)) return;
        if (w.key_mods(e.key, e.shiftKey, true, e.altKey, now())) e.preventDefault();
        after(); return;
      }
      const text = w.text_focused();
      if (e.altKey && !text) return;
      // In a text field characters arrive as input events (so the input method can take them).
      if (text && e.key.length === 1) return;
      if (w.key_mods(e.key, e.shiftKey, false, e.altKey, now()) || e.key === 'Tab') e.preventDefault();
      after();
    });
    ta.addEventListener('input', e => {
      if (e.isComposing) return;
      if (e.inputType === 'insertLineBreak') w.key_mods('Enter', false, false, false, now());
      // A composition's text comes through the composition events.
      else if (e.data && e.inputType !== 'insertCompositionText') w.text_input(e.data, now());
      ta.value = ''; after();
    });
    ta.addEventListener('compositionupdate', e => { w.ime_preedit(e.data || '', now()); after(); });
    ta.addEventListener('compositionend', e => { w.ime_commit(e.data || '', now()); ta.value = ''; after(); });
    document.addEventListener('copy', e => { const t = w.copy(); if (t != null) { e.clipboardData.setData('text/plain', t); e.preventDefault(); } });
    document.addEventListener('cut', e => { const t = w.cut(now()); if (t != null) { e.clipboardData.setData('text/plain', t); e.preventDefault(); after(); } });
    document.addEventListener('paste', e => { const t = e.clipboardData.getData('text/plain'); if (t && w.paste(t, now())) { e.preventDefault(); after(); } });
    (opts.keys || window).addEventListener('keyup', e => { w.key_up(e.key, now()); after(); });
    // Reduced motion: the application's own moving parts rest (App::set_reduced_motion in Rust).
    const rm = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
    if (rm) { w.set_reduced_motion(rm.matches); if (rm.addEventListener) rm.addEventListener('change', e => { w.set_reduced_motion(e.matches); kick(); }); }
    // The system's appearance: dark or light, and more contrast (App::set_appearance in Rust).
    const mq = q => window.matchMedia ? window.matchMedia(q) : null;
    const dark = mq('(prefers-color-scheme: dark)'), contrast = mq('(prefers-contrast: more)');
    const look = () => { w.set_appearance(!!(dark && dark.matches), !!(contrast && contrast.matches)); after(); };
    w.set_appearance(!!(dark && dark.matches), !!(contrast && contrast.matches));
    for (const m of [dark, contrast]) if (m && m.addEventListener) m.addEventListener('change', look);
    // Files dropped on the canvas: read in the page, handed over one by one, then together (App::files_dropped).
    let over = false;
    const hover = on => { if (on !== over) { over = on; w.files_hovering(on); after(); } };
    canvas.addEventListener('dragover', e => { if (e.dataTransfer && [...e.dataTransfer.types].includes('Files')) { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; hover(true); } });
    canvas.addEventListener('dragleave', () => hover(false));
    canvas.addEventListener('drop', async e => {
      if (!e.dataTransfer || !e.dataTransfer.files.length) return;
      e.preventDefault();
      over = false;
      for (const f of e.dataTransfer.files) w.drop_file(f.name, new Uint8Array(await f.arrayBuffer()));
      w.drop_done(now()); after();
    });
    window.addEventListener('hashchange', kick);
    new ResizeObserver(() => { fit(); w.resize(canvas.width, canvas.height, dpr); kick(); }).observe(stage);
    kick();
    // What a host can change from outside: the page (or a look:v1: recipe), the theme and material by
    // name, the language by tag.
    return {
      route: h => { const ok = w.route(h); after(); return ok; },
      look: (theme, material) => { w.set_look(theme || '', material || ''); after(); },
      locale: tag => { w.set_locale(tag || ''); after(); },
      focus: () => canvas.focus({ preventScroll: true }),
    };
  } catch (e) { if (msg) msg.textContent = (opts.failed || 'This browser could not start graphics: ') + (e && e.message ? e.message : e); console.error(e); throw e; }
}
